entries[78343] = { ["name"] = "Formel: Handschuhe - Kräuterkunde", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Verzauberkunst (145)\nBenutzen: Lehrt Euch, Handschuhe dauerhaft zu verzaubern, sodass die Kräuterkundefertigkeit um 2 erhöht wird.\nHandschuhe dauerhaft verzaubern, sodass die Kräuterkundefertigkeit um 2 erhöht wird.\nVerkaufspreis:" }
entries[78345] = { ["name"] = "Muster: Grüne Drachenschuppengamaschen", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Lederverarbeitung (270)\nBenutzen: Lehrt Euch die Herstellung von grünen Drachenschuppengamaschen.\nVerkaufspreis:\nGrüne Drachenschuppengamaschen\nWird beim Anlegen gebunden\nBeine Kette\n327 Rüstung\n+21 Ausdauer\n+22 Intelligenz\n+11 Naturwiderstand\nHaltbarkeit 100 / 100\nBenötigt Stufe 49\n\nGrüner Drachenschuppenpanzer (0/3)\nGrüne Drachenschuppenbrustplatte\nGrüne Drachenschuppengamaschen\nGrüne Drachenschuppenstulpen\nVerkaufspreis:\nBenötigt Unverwüstliches Leder (20), Grüne Drachenschuppe (25), Runenfaden" }
entries[78346] = { ["name"] = "Muster: Grüne Drachenschuppenbrustplatte", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Lederverarbeitung (260)\nBenutzen: Lehrt Euch die Herstellung einer grünen Drachenschuppenbrustplatte.\nVerkaufspreis:\nGrüne Drachenschuppenbrustplatte\nWird beim Anlegen gebunden\nBrust Kette\n361 Rüstung\n+20 Ausdauer\n+22 Intelligenz\n+11 Naturwiderstand\nHaltbarkeit 135 / 135\nBenötigt Stufe 47\n\nGrüner Drachenschuppenpanzer (0/3)\nGrüne Drachenschuppenbrustplatte\nGrüne Drachenschuppengamaschen\nGrüne Drachenschuppenstulpen\nVerkaufspreis:\nBenötigt Unverwüstliches Leder (20), Grüne Drachenschuppe (25), Runenfaden (2)" }
entries[78348] = { ["name"] = "Formel: Waffe - Scharfrichter", ["text"] = "Benötigt Verzauberkunst (375)\nBenutzen: Lehrt Euch120 Nahkampfwaffen dauerhaft zu verzaubern120 sodass Euch manchmal 120 kritische Trefferwert gewährt werden. Erfordert einen Gegenstand der Stufe 120 oder höher.\nEine Nahkampfwaffe dauerhaft verzaubern, sodass der kritische Trefferwert gelegentlich um 120 erhöht wird. Dieser Effekt ist nicht stapelbar.\nVerkaufspreis:" }
