entries[79023] = { ["name"] = "Fischadlerfederkiel", ["text"] = "Questgegenstand\nBenutzen: Fügt 10 Fischadlerfederkiele zu einer Fischadlerfederbürste zusammen. (3 Sek. Abklingzeit)\n\"Die harten Kiele sind braun, schwarz und weiß gefleckt.\"" }
