entries[79120] = { ["name"] = "Moguartefakt", ["text"] = "Questgegenstand\n\"Dieses scheinbar einfache Relikt ist von Staub bedeckt, von der Zeit gezeichnet und brodelt vor arkaner Energie.\"" }
