entries[79163] = { ["name"] = "Kaiserlicher Lotusumschlag", ["text"] = "Questgegenstand\nBenutzen: Belebt einen Gesandten von Steinpflug wieder.\n\"Dieses Kräuterpräparat ist mit heiliger Energie durchzogen.\"" }
entries[79197] = { ["name"] = "Lichtungsglühwurm", ["text"] = "Questgegenstand\n\"Wenn Ihr ein Fisch wärt, würde das hier absolut schmackhaft aussehen.\"" }
