entries[79201] = { ["name"] = "Verblichene Glyphe", ["text"] = "Klassen: Hexenmeister\n\"Die Magie dieser Glyphe ist verflogen, aber die Inschrift ist immer noch wunderschön anzusehen.\"\nVerkaufspreis:" }
