entries[79249] = { ["name"] = "Foliant des klaren Geistes", ["text"] = "\"Dieser Foliant wird von Inschriftenhändlern verkauft und von Schreibern hergestellt. Er ist nötig, um mächtige Glyphen und Talente zu entfernen, damit neue gewählt werden können. Nur mit Stufe 86 oder höher zu verwenden.\"\nVerkaufspreis:" }
