entries[79320] = { ["name"] = "Halbierter hübscher Apfel", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Stufe 90\nBenutzen: Stellt im Verlauf von 10 Sek. 120000 Gesundheit und ( 24000 * 5) Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang 90 Ausdauer. Außerdem fühlt Ihr Euch sehr gesund! (1 Min Abklingzeit)\n\"Die Hälfte eines saftigen Apfels.\"" }
