entries[79327] = { ["name"] = "Reliquie von Xuen", ["text"] = "Wird beim Anlegen gebunden\nEinzigartig anlegbar: [Darkmoon Card of the Mists] (1)\nSchmuck\n+956 Stärke\nBenötigt Stufe 90\nAnlegen: Eure Nahkampfangriffe gewähren eine Chance, Euch 'Segen der Erhabenen' zu gewähren und Eure Stärke 15 Sek. lang um 3027 zu erhöhen. (20% Chance, 55 Sek. Abklingzeit) (Procchance: 20%, 55s Abklingzeit)\nVerkaufspreis:" }
entries[79328] = { ["name"] = "Reliquie von Xuen", ["text"] = "Wird beim Anlegen gebunden\nEinzigartig anlegbar: [Darkmoon Card of the Mists] (1)\nSchmuck\n+956 Beweglichkeit\nBenötigt Stufe 90\nAnlegen: Eure kritischen Distanz- und Nahkampftreffer haben eine Chance, Euch 'Segen der Erhabenen' zu gewähren und Eure Beweglichkeit 15 Sek. lang um 3027 zu erhöhen. (Procchance: 20%, 55s Abklingzeit)\nVerkaufspreis:" }
entries[79329] = { ["name"] = "Relikt von Niuzao", ["text"] = "Wird beim Anlegen gebunden\nEinzigartig anlegbar: [Darkmoon Card of the Mists] (1)\nSchmuck\n+1.434 Ausdauer\nBenötigt Stufe 90\nBenutzen: Gewährt 10 Sek. lang 8871 Ausweichen. (1 Min Abklingzeit)\nVerkaufspreis:" }
entries[79330] = { ["name"] = "Relikt von Chi-Ji", ["text"] = "Wird beim Anlegen gebunden\nEinzigartig anlegbar: [Darkmoon Card of the Mists] (1)\nSchmuck\n+1.157 Intelligenz\nBenötigt Stufe 90\nAnlegen: Eure Heilzauber haben eine Chance, Euch 'Segen der Erhabenen' zu gewähren und Eure Willenskraft 20 Sek. lang um 3027 zu erhöhen. (20% Chance, 55 Sek. Abklingzeit) (Procchance: 20%, 55s Abklingzeit)\nVerkaufspreis:" }
entries[79331] = { ["name"] = "Reliquie von Yu'lon", ["text"] = "Wird beim Anlegen gebunden\nEinzigartig anlegbar: [Darkmoon Card of the Mists] (1)\nSchmuck\n+956 Intelligenz\nBenötigt Stufe 90\nAnlegen: Wenn Ihr Zauberschaden verursacht, besteht eine Chance, dass Ihr den Effekt 'Segen der Erhabenen' erhaltet, der Eure Intelligenz 15 Sek. lang um 3027 erhöht. (Procchance: 20%, 50s Abklingzeit)\nVerkaufspreis:" }
