entries[79339] = { ["name"] = "Regenmohnstab", ["text"] = "Wird beim Anlegen gebunden\nZweihändig Stab\n3,015 - 4,523 Schaden Tempo 3.30\n(1,142 Schaden pro Sekunde)\n+938 Ausdauer\n+625 Intelligenz\nErhöht Eure Tempowertung um + 417.\nErhöht die Zaubermacht um + 3.581.\nErhöht Eure Meisterschaftswertung um + 417.\nHaltbarkeit 100 / 100\nBenötigt Stufe 85\nVerkaufspreis:" }
