entries[79341] = { ["name"] = "Beschrifteter Schlangenstab", ["text"] = "Accountgebunden\nZweihändig Stab\n4,895 - 7,343 Schaden Tempo 3.30\n(1,854 Schaden pro Sekunde)\n+1.522 Ausdauer\n+1.015 Intelligenz\nErhöht Eure Trefferwertung um + 677.\nErhöht die Zaubermacht um + 5.813.\nErhöht Eure Meisterschaftswertung um + 677.\nHaltbarkeit 120 / 120\nBenötigt Stufe 90\nVerkaufspreis:" }
entries[79342] = { ["name"] = "Geistereisenstab", ["text"] = "Wird beim Anlegen gebunden\nZweihändig Stab\n6,030 - 9,046 Schaden Tempo 3.30\n(2,284 Schaden pro Sekunde)\n+625 Beweglichkeit\n+938 Ausdauer\nErhöht Eure kritische Trefferwertung um + 417.\nErhöht Eure Meisterschaftswertung um + 417.\nHaltbarkeit 100 / 100\nBenötigt Stufe 85\nVerkaufspreis:" }
