entries[79344] = { ["name"] = "Pomerntefeuerwerk", ["text"] = "Questgegenstand\nBenutzen: Schießt Feuerwerk ab, um in der Nähe befindliche Pomfrüchte von ihren Zweigen zu schütteln. (3 Sek. Abklingzeit)" }
entries[79513] = { ["name"] = "Glyphe 'Gedankenschinden'", ["text"] = "Erhebliche Glyphe\nKlassen: Priester\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Gedankenschinden' verringert das Bewegungstempo des Ziels nicht mehr. Stattdessen wird jedes Mal, wenn 'Gedankenschinden' Schaden verursacht, Euer Bewegungstempo 5 Sek. lang um 15% erhöht. Dieser Effekt ist bis zu 3-mal stapelbar.\nVerkaufspreis:" }
entries[79514] = { ["name"] = "Glyphe 'Schattenwort: Tod'", ["text"] = "Erhebliche Glyphe\nKlassen: Priester\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Schattenwort: Tod' kann jetzt jederzeit gewirkt werden, fügt Zielen mit über 20% Gesundheit jedoch nur 25% des Schadens zu [ Gedankenschinden : und erzeugt beim Einsatz gegen sie keine Schattenkugeln mehr ].\n\nDas Wirken von 'Schattenwort: Tod' fügt Euch nun Schaden in Höhe des Schadens zu, den der Zauber einem Gegner mit mehr als 20% Gesundheit zufügen würde.\nVerkaufspreis:" }
entries[79515] = { ["name"] = "Glyphe 'Vampirumarmung'", ["text"] = "Erhebliche Glyphe\nKlassen: Priester\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Vampirumarmung' wandelt zusätzliche 50% Eures verursachten Schadens in Heilung um, die Gesamtdauer des Effekts wird jedoch um 5 Sek. verringert.\nVerkaufspreis:" }
entries[79538] = { ["name"] = "Glyphe 'Jindujun'", ["text"] = "Geringe Glyphe\nKlassen: Priester\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nZiele Eures Zaubers 'Levitieren' reiten nun während der Effektdauer auf einer Wolke." }
entries[79710] = { ["name"] = "Glyphe", ["text"] = "Klassen: Mönch\nBenötigt Stufe 25" }
entries[79713] = { ["name"] = "Dynastische Tafel", ["text"] = "Questgegenstand\n\"Auf dieser Tafel befindet sich eine uralte, von der Zeit verwitterte Inschrift.\"" }
