entries[79771] = { ["name"] = "Teufelsdrache", ["text"] = "Einzigartig\nReittier\nBenötigt Stufe 20\nBenötigt Unerfahrener Reiter\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Das ist ein Flugreittier.\nBeschwört einen reitbaren Teufelsdrachen oder gibt ihn wieder frei. Das ist ein Flugreittier." }
entries[79780] = { ["name"] = "Spiegelschreiter", ["text"] = "Questgegenstand\n\"Winzig aber schmackhaft.\"" }
entries[79784] = { ["name"] = "Taucherhelm", ["text"] = "Questgegenstand\nEinzigartig\nKopf" }
entries[79802] = { ["name"] = "Zügel der Jadewolkenschlange", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\nBenötigt Stufe 90\nBenötigt Gekonntes Reiten\nBenötigt Orden der Wolkenschlange\n- Ehrfürchtig\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Das ist ein Flugreittier. Benötigt 'Wolkenschlangenreiten' vom Orden der Wolkenschlange.\nBeschwört eine reitbare Jadewolkenschlange oder gibt sie wieder frei. Das ist ein Flugreittier. Benötigt 'Wolkenschlangenreiten' vom Orden der Wolkenschlange.\nVerkaufspreis:" }
entries[79806] = { ["name"] = "Pfeil für Kommandantin Hsieh", ["text"] = "Questgegenstand\n\"Diese Pandarenpfeile sind wirklich spitz!\"" }
entries[79807] = { ["name"] = "Stab des Wassersprechers", ["text"] = "Questgegenstand\n\"Ein alter, knorriger Stab, in den Worte der Macht geschnitzt wurden. Er ist mit allerhand Relikten behangen.\"" }
entries[79808] = { ["name"] = "Zeremonielle Roben", ["text"] = "Questgegenstand\n\"Mit Runen und Symbolen bedeckte Seidenroben.\"" }
entries[79809] = { ["name"] = "Jadekrone", ["text"] = "Questgegenstand\n\"Ein schwerer Kopfschmuck, der aus einem einzigen Stück Jade geschnitzt wurde.\"" }
entries[79810] = { ["name"] = "Rosenholzperlen", ["text"] = "Questgegenstand\n\"Von Jahren der Gebete ganz glattpoliert.\"" }
entries[79811] = { ["name"] = "Erbstück der Perlflossen", ["text"] = "Questgegenstand\n\"Unbezahlbar.\"" }
entries[79812] = { ["name"] = "Umhang der Allianz", ["text"] = "Questgegenstand\nDieser Gegenstand startet eine Quest.\n\"Zusammengesetzt ergeben die Fetzen einen vormals königlichen Umhang.\"" }
entries[79813] = { ["name"] = "Fetzen der Allianz", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (3)\nBenutzen: Fügt 3 Fetzen der Allianz zusammen, um ihre ursprüngliche Form wiederherzustellen.\n\"Ein Stofffetzen in den Farben der Allianz. Bei den Langfingern der Schlingschwänze können vielleicht noch mehr gefunden werden.\"" }
entries[79819] = { ["name"] = "Dit Da Jow", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Ein populäres Einreibemittel, das aus diversen Kräutern besteht, die in einer geheimen Mischung zusammengestellt wurden. Heilt unter Garantie sofort blaue Flecken und kleinere Verletzungen. (5 Sek. Abklingzeit)" }
entries[79823] = { ["name"] = "Benutztes Papier", ["text"] = "Questgegenstand\nDieser Gegenstand startet eine Quest.\n\"Ihr wollt nicht wissen, wofür es benutzt wurde.\"" }
entries[79824] = { ["name"] = "Gestohlenes Gemüse", ["text"] = "Questgegenstand\n\"Scheint... größtenteils unbeschädigt.\"" }
entries[79825] = { ["name"] = "Versorgungsgüter aus Zhus Wacht", ["text"] = "Questgegenstand\nEinzigartig\n\"Getreide, Gewürze und Pökelfleisch sind fein säuberlich verstaut.\"" }
entries[79826] = { ["name"] = "Verschossener Shado-Pan-Pfeil", ["text"] = "Questgegenstand\n\"Ein Paradebeispiel für 'Hauptsache weit - wen interessiert, ob's trifft'.\"" }
entries[79827] = { ["name"] = "Authentisches Pfannengericht nach Vier-Winde-Art", ["text"] = "Questgegenstand\n\"Riecht scharf.\"" }
entries[79828] = { ["name"] = "Yakstatuette", ["text"] = "Questgegenstand\n\"Für ein Artefakt der Ho-zen ist es erstaunlich kunstfertig geschnitzt.\"" }
entries[79833] = { ["name"] = "Dimmlichttrüffel", ["text"] = "Questgegenstand\n\"Ihr Schimmer lässt merklich nach, sobald sie aus dem Boden gezogen wird.\"" }
entries[79864] = { ["name"] = "Glühmagenpfefferschote", ["text"] = "Questgegenstand\n\"Scharf genug, um Haut zu verätzen. Schutzhandschuhe werden dringend empfohlen!\"" }
entries[79866] = { ["name"] = "Legendenbuch der Kunzen", ["text"] = "Questgegenstand\n\"Eine ungebundene Sammlung von Kurzgeschichten, Sprichwörtern der Ho-zen und anstößigen Bildern.\"" }
entries[79867] = { ["name"] = "Fettiges Ziegensteak", ["text"] = "Questgegenstand\n\"Das Vieh der Kunzen hat bei weitem kein solches Wildaroma wie die einheimischen Ziegen des Tals.\"" }
entries[79868] = { ["name"] = "Pandarische Tonscherbe", ["text"] = "\"Schlüsselstein, der archäologische Artefakte der Pandaren mit fehlenden Fragmenten vervollständigen kann.\"\nVerkaufspreis:" }
entries[79869] = { ["name"] = "Bruchstück einer Mogustatue", ["text"] = "\"Schlüsselstein, der archäologische Artefakte der Mogu mit fehlenden Fragmenten vervollständigen kann.\"\nVerkaufspreis:" }
entries[79870] = { ["name"] = "Yu-Ping-Suppe", ["text"] = "Questgegenstand\n\"Eine Suppe aus Fisch, Äpfeln und Kräutern.\"" }
entries[79871] = { ["name"] = "Pikante Garnelenklößchen", ["text"] = "Questgegenstand\n\"'Pikant' ist untertrieben.\"" }
entries[79875] = { ["name"] = "Der Gesang des Tals", ["text"] = "Questgegenstand\n\"Das Papier ist sehr alt und fragil. Das Gedicht darauf wurde mit sicheren, eleganten Pinselstrichen verfasst.\"\n<Zum Lesen rechtsklicken>" }
entries[79880] = { ["name"] = "Gestohlene Versorgungsgüter", ["text"] = "Questgegenstand\n\"Die Güter wurden im Kampf leicht beschädigt, aber Händler Shi sollte trotzdem keine Probleme haben, sie an den Mann zu bringen.\"" }
entries[79884] = { ["name"] = "Eimer mit glitschigem Wasser", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Auf einen wenig motivierten Ho-zen werfen.\n\"Der Gestank ist nicht auszuhalten.\"" }
entries[79885] = { ["name"] = "Fass mit Feuerwerkskörpern", ["text"] = "Questgegenstand\n\"Gewöhnlicherweise für Feste verwendet. Heute... werden sie der RACHE dienen.\"" }
entries[79894] = { ["name"] = "Mushanschwanzeintopf", ["text"] = "Questgegenstand\n\"RICHTIG zubereitet: auf einem Berg.\"" }
entries[79895] = { ["name"] = "Topf des Meisters", ["text"] = "Questgegenstand\nBenutzen: Setzt dies in der Nähe des Lagerfeuers in Kunzen ein, um Mushanschwanzeintopf zuzubereiten." }
