entries[80596] = { ["name"] = "Fass voll Schwarzpulver", ["text"] = "Questgegenstand\nEinzigartig (20)\n\"Ganz, ganz vorsichtig!\"" }
entries[80597] = { ["name"] = "Faszinierendes Relikt der Mogu", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\nBenötigt Stufe 87\n\"Noch elf davon und man kann sie zu barer Münze machen.\"" }
entries[80598] = { ["name"] = "Zhens Banner", ["text"] = "Questgegenstand\nEinzigartig\n\"Ihr habt die Ehre des Shado-Meisters wiederhergestellt.\"" }
entries[80599] = { ["name"] = "Goblinangelbombe", ["text"] = "Questgegenstand\nBenutzen: Werft die Goblinangelbombe und hofft das Beste!" }
entries[80600] = { ["name"] = "Stachel", ["text"] = "Questgegenstand\n\"Vorsicht, sehr scharf.\"" }
entries[80610] = { ["name"] = "Herbeigezauberter Manapudding", ["text"] = "Herbeigezauberter Gegenstand\nEinzigartig (80)\nBenötigt Stufe 90\nBenutzen: Stellt im Verlauf von 20 Sek. 300000 Gesundheit und ( 75000 / 5 * 20) Mana wieder her. Ihr müsst beim Essen sitzen bleiben." }
