entries[80678] = { ["name"] = "Purpurrote Schwanzfeder", ["text"] = "Questgegenstand\n\"Nicht sehr schwer.\"" }
entries[80679] = { ["name"] = "Dunkle Schwanzfeder", ["text"] = "Questgegenstand\n\"Die Farbe wechselt im Sonnenlicht zwischen Indigo und Violett.\"" }
entries[80685] = { ["name"] = "Holzbrett", ["text"] = "Questgegenstand\n\"Man müsste nur genügend davon zusammenbinden und man hätte ein recht stabiles Floß.\"" }
